      draft_task_id: null, // 高级剪辑没有 draft_task_id
      timeline: composePlan.timeline,
      pipeline: {
        use_transitions: false,
        transition_type: 'fade',
        transition_duration: 0.5,
        resync_subtitle: true,
      },
      subtitle: subtitleConfig, // 🎨 传递完整字幕配置
      audio: {
        bgm_url: null,
        bgm_volume: 0.3,
        original_volume: 1.0,
      },
      output: { need_ass: true },
    }

    console.log('[ExportPanelVFS] 调用后端 compose API:', composeReq)

    // 调用后端 API
    const response = await fetch(`${apiBaseUrl}/v1/tasks/compose-from-timeline`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(composeReq),
    })

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({ message: '合成请求失败' }))
      throw new Error(errorData.message || '发起合成任务失败')
    }

    const composeData = await response.json()
    const composeTaskId = composeData.data.task_id

    console.log('[ExportPanelVFS] 合成任务已创建:', composeTaskId)

    // 轮询任务状态
    const pollInterval = setInterval(async () => {
      try {
        const statusRes = await fetch(`${apiBaseUrl}/v1/tasks/${composeTaskId}`, {
          headers: {
            'Authorization': `Bearer ${apiKey}`,
          },
        })

        if (!statusRes.ok) {
          clearInterval(pollInterval)
          throw new Error('获取任务状态失败')
        }

        const statusData = await statusRes.json()
        const task = statusData.data

        setProgress(Math.min(95, Math.round((task.progress || 0) * 0.95)))

        if (task.stage === 'succeeded') {
          clearInterval(pollInterval)

          // 获取成片文件 URL
          const fileRes = await fetch(`${apiBaseUrl}/v1/tasks/${composeTaskId}/files/final_video`, {
            headers: {
              'Authorization': `Bearer ${apiKey}`,
            },
          })

          if (fileRes.ok) {
            const fileData = await fileRes.json()
            const videoUrl = fileData.data.url

            // 下载视频并保存到 VFS
            const videoBlob = await fetch(videoUrl).then(r => r.blob())
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5)
            const projectName = '默认项目'
            const savePath = buildVFSPath(projectName, `${PROJECT_FOLDERS.OUTPUT}/export_${timestamp}.mp4`)

            await vfs.writeFile(savePath, videoBlob)

            setStatus('complete')
            setProgress(100)
            alert(`🎉 视频已成功导出到项目目录:\n${savePath}\n\n您可以前往"文件浏览"查看或使用。`)
          }
        } else if (task.stage === 'failed') {
          clearInterval(pollInterval)
          throw new Error(task.error_message || '合成任务失败')
        } else if (task.stage === 'cancelled') {
          clearInterval(pollInterval)
          throw new Error('合成任务已取消')
        }
      } catch (err) {
        clearInterval(pollInterval)
        throw err
      }
    }, 2000)

  } catch (err) {
    console.error('[ExportPanelVFS] 后端导出失败:', err)
    setStatus('error')
    setErrorMessage(err.message || '后端处理失败')
  }
}

